package com.secure.documentwallet;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.Build;import androidx.core.app.*;
public class ExpiryReceiver extends BroadcastReceiver {
 @Override public void onReceive(Context c,Intent source){ExpiryScheduler.channel(c);if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;String id=source.getStringExtra("id"),title=source.getStringExtra("title");if(id==null)id="expiry";if(title==null)title="Document";int days=source.getIntExtra("days",0);Intent open=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);PendingIntent content=PendingIntent.getActivity(c,id.hashCode(),open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String message=days==0?title+" expires today":title+" expires in "+days+" day"+(days==1?"":"s");Notification notification=new NotificationCompat.Builder(c,ExpiryScheduler.CHANNEL).setSmallIcon(R.drawable.ic_vault_square).setContentTitle("My Vault Expiry Reminder").setContentText(message).setStyle(new NotificationCompat.BigTextStyle().bigText(message+". Open My Vault to review or renew it.")).setContentIntent(content).setAutoCancel(true).setPriority(NotificationCompat.PRIORITY_HIGH).build();NotificationManagerCompat.from(c).notify(id.hashCode()+days,notification);}
}
